/**
 * Hagar in Wilderness
 * -------------------
 * Sarai's Egyptian maid Hagar flees into the desert of Shur, where an angel of the Lord meets her at a spring and promises a son, Ishmael. Stage: a lone palm and hot spring in bleached sand; Hagar seated, startled, water jar at her feet; white heat, trembling mirage light.
 *
 * Palette 0xd8b878 → 0x9c8456 · light: dawn · hero: jar
 * Game beat: Find water and listen before acting.
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./abraham-kit.js.
 */

import { THREE, createScene, water, palm, well, jar, person } from './abraham-kit.js';

const BG = 0xd8b878;
const GROUND = 0x776542;

export function build(group) {
    const W = createScene(group, { seed: 4010650305, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dawn */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-58, 30, -145], 9, 0xffd9a0);
    W.disc([-58, 30, -155], 16, 0xffb060, 0.22);
    W.stars(60, 150, [0xcfd8e8, 0xbfd0e0], 0.55);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-60, 34, -120, 24], [10, 40, -135, 30], [70, 33, -125, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xd8c8b8, { opacity: 0.5 }), [x, y, z], { s: [s, s * 0.24, s * 0.5] });
    });
    W.backdrop(clouds);

    /* river: animated water between grassy banks */
    water(W, group, 260, 26, -0.4, 0x2a2317, 0xb39863);
    W.ground(260, 95, 0, 60, 0x776542, { amp: 0.5, j: 0.3, flat: 24, fz: 54 });
    W.ground(260, 95, 0, -64, 0x655638, { amp: 0.6, j: 0.3, flat: 24, fz: -58 });
    W.add(group, W.G('box', 260, 0.3, 4), W.mat(0x413824), [0, -0.05, 12.6]);
    W.add(group, W.G('box', 260, 0.3, 4), W.mat(0x413824), [0, -0.05, -14.6]);

    /* palms: dappled shade at the scene's edge */
    palm(W, group, -83.4, 0, -38.5, 1.37, { leafA: 0x4f8a2e, leafB: 0x5fa036 });
    palm(W, group, 76.1, 0, -41.8, 1.12, { leafA: 0x4f8a2e, leafB: 0x5fa036 });
    palm(W, group, -40.6, 0, -64.6, 1.34, { leafA: 0x4f8a2e, leafB: 0x5fa036 });
    palm(W, group, -68.6, 0, -67.1, 0.98, { leafA: 0x4f8a2e, leafB: 0x5fa036 });
    palm(W, group, -2.1, 0, -45.7, 1.45, { leafA: 0x4f8a2e, leafB: 0x5fa036 });

    well(W, group, -2.4, 0, 2.7, );

    /* hero: the jar */
    jar(W, group, 0, 0, 11, 1.25, { clay: 0x8c774d });
    W.disc([0, 4, 1], 4, 0xffef9c, 0.3);

    /* figures */
    person(W, group, [-5, 0, 16], { robe: 0xd8b878, bend: 1.05, armR: [0.2, 0.1], armL: [0.2, -0.1], ry: 0.69, s: 1.10 });
    person(W, group, [4.5, 0, 17], { robe: 0x9c8456, bend: 1.05, armR: [0.2, 0.1], armL: [0.2, -0.1], ry: 0.17, s: 1.04 });

    return W.finish();
}

export default { build };
